mapper.select:
SELECT s.store_code AS storeCode, s.store_name AS storeName, s.store_level AS storeLevel, s.city, s.province, COALESCE(ci.coupon_count, 0) AS couponCount, COALESCE(bul.redeem_count, 0) AS redeemCount, COALESCE(bul.redeem_amount, 0) AS redeemAmount, COALESCE(co.refund_count, 0) AS refundCount, COALESCE(co.refund_amount, 0) AS refundAmount, COALESCE(rr.risk_count, 0) AS riskCount, COALESCE(ab.used_budget, 0) AS budgetUsed, COALESCE(ab.total_budget, 0) AS budgetTotal, CASE WHEN COALESCE(ab.total_budget, 0) > 0 THEN ROUND(COALESCE(ab.used_budget, 0) / ab.total_budget * 100, 2) ELSE 0 END AS budgetUsageRate, CASE WHEN COALESCE(ci.coupon_count, 0) > 0 THEN ROUND(COALESCE(bul.redeem_count, 0) / ci.coupon_count * 100, 2) ELSE 0 END AS redeemRate FROM t_store_info s LEFT JOIN ( SELECT store_code, COUNT(*) AS coupon_count FROM t_coupon_instance WHERE receive_time >= #{startDate} AND receive_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND is_deleted = 0 AND store_code IS NOT NULL GROUP BY store_code ) ci ON s.store_code = ci.store_code LEFT JOIN ( SELECT store_code, COUNT(*) AS redeem_count, COALESCE(SUM(benefit_value), 0) AS redeem_amount FROM t_benefit_use_log WHERE use_status = 2 AND confirm_time >= #{startDate} AND confirm_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND is_deleted = 0 AND store_code IS NOT NULL GROUP BY store_code ) bul ON s.store_code = bul.store_code LEFT JOIN ( SELECT store_code, COUNT(*) AS refund_count, COALESCE(SUM(refund_amount), 0) AS refund_amount FROM t_consume_order WHERE order_status = 5 AND refund_time >= #{startDate} AND refund_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND is_deleted = 0 AND store_code IS NOT NULL GROUP BY store_code ) co ON s.store_code = co.store_code LEFT JOIN ( SELECT store_code, COUNT(*) AS risk_count FROM t_risk_record WHERE handle_result = 3 AND create_time >= #{startDate} AND create_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND is_deleted = 0 AND store_code IS NOT NULL GROUP BY store_code ) rr ON s.store_code = rr.store_code LEFT JOIN ( SELECT store_code, COALESCE(SUM(total_budget), 0) AS total_budget, COALESCE(SUM(used_budget), 0) AS used_budget FROM t_activity_budget WHERE store_code IS NOT NULL AND is_deleted = 0 GROUP BY store_code ) ab ON s.store_code = ab.store_code WHERE s.status = 1 AND s.is_deleted = 0
AND s.store_code = #{storeCode}
AND s.city = #{city}
AND s.province = #{province}
ORDER BY redeemAmount DESC

SELECT a.id AS activityId, a.activity_code AS activityCode, a.activity_name AS activityName, a.activity_type AS activityType, COALESCE(ci.coupon_count, 0) AS couponCount, COALESCE(bul.redeem_count, 0) AS redeemCount, COALESCE(bul.redeem_amount, 0) AS redeemAmount, COALESCE(a.driven_order_count, 0) AS drivenOrderCount, COALESCE(a.driven_order_amount, 0) AS drivenOrderAmount, COALESCE(ab.used_budget, 0) AS budgetUsed, COALESCE(ab.total_budget, 0) AS budgetTotal, CASE WHEN COALESCE(ab.total_budget, 0) > 0 THEN ROUND(COALESCE(ab.used_budget, 0) / ab.total_budget * 100, 2) ELSE 0 END AS budgetUsageRate, a.status AS status, DATEDIFF(a.end_time, NOW()) AS daysLeft FROM t_activity a LEFT JOIN ( SELECT ct.activity_id, COUNT(*) AS coupon_count FROM t_coupon_instance ci INNER JOIN t_coupon_template ct ON ci.template_id = ct.id AND ct.is_deleted = 0 WHERE ci.receive_time >= #{startDate} AND ci.receive_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND ci.is_deleted = 0 GROUP BY ct.activity_id ) ci ON a.id = ci.activity_id LEFT JOIN ( SELECT benefit_id, COUNT(*) AS redeem_count, COALESCE(SUM(benefit_value), 0) AS redeem_amount FROM t_benefit_use_log WHERE use_status = 2 AND confirm_time >= #{startDate} AND confirm_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND benefit_type = 1 AND is_deleted = 0 GROUP BY benefit_id ) bul ON a.id = bul.benefit_id LEFT JOIN ( SELECT activity_id, COALESCE(SUM(total_budget), 0) AS total_budget, COALESCE(SUM(used_budget), 0) AS used_budget FROM t_activity_budget WHERE store_code IS NULL AND is_deleted = 0 GROUP BY activity_id ) ab ON a.id = ab.activity_id WHERE a.is_deleted = 0
AND a.id = #{activityId}
ORDER BY redeemAmount DESC

SELECT m.level_code AS levelCode, COALESCE(mc.member_count, 0) AS memberCount, COALESCE(ci.coupon_count, 0) AS couponCount, COALESCE(bul.redeem_count, 0) AS redeemCount, COALESCE(bul.redeem_amount, 0) AS redeemAmount, CASE WHEN COALESCE(mc.member_count, 0) > 0 THEN ROUND(COALESCE(ci.coupon_count, 0) / mc.member_count, 2) ELSE 0 END AS avgCouponPerMember FROM ( SELECT DISTINCT level_code FROM t_member WHERE is_deleted = 0
AND level_code = #{levelCode}
) m LEFT JOIN ( SELECT level_code, COUNT(*) AS member_count FROM t_member WHERE is_deleted = 0
AND level_code = #{levelCode}
GROUP BY level_code ) mc ON m.level_code = mc.level_code LEFT JOIN ( SELECT mm.level_code, COUNT(*) AS coupon_count FROM t_coupon_instance ci INNER JOIN t_member mm ON ci.member_id = mm.id AND mm.is_deleted = 0 WHERE ci.receive_time >= #{startDate} AND ci.receive_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND ci.is_deleted = 0
AND mm.level_code = #{levelCode}
GROUP BY mm.level_code ) ci ON m.level_code = ci.level_code LEFT JOIN ( SELECT mm.level_code, COUNT(*) AS redeem_count, COALESCE(SUM(bul.benefit_value), 0) AS redeem_amount FROM t_benefit_use_log bul INNER JOIN t_member mm ON bul.member_id = mm.id AND mm.is_deleted = 0 WHERE bul.use_status = 2 AND bul.confirm_time >= #{startDate} AND bul.confirm_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND bul.is_deleted = 0
AND mm.level_code = #{levelCode}
GROUP BY mm.level_code ) bul ON m.level_code = bul.level_code ORDER BY m.level_code
